//--------------------------------------------------------------------------
/**
 * Downloads an asset payload in a given format. Only mesh is supported for the moment. This endpoint requires special export permission.
 */
export function exportAsset<T extends 'arraybuffer' | 'stream' | 'json' | 'text' = 'arraybuffer'>(
    {
        asset_container_exportable,
        asset_id,
        format,
        scale = 1,
        sub_mesh_index,
    }: {
        asset_container_exportable: 'meshes' | 'sounds';
        asset_id: string;
        format: 'obj' | 'stl';
        scale?: number;
        sub_mesh_index?: number;
    },
    headers?: AxiosRequestHeaders,
    responseType?: T,
): AxiosPromise<
    T extends 'arraybuffer'
        ? ArrayBuffer
        : T extends 'json'
          ? object
          : T extends 'text'
            ? string
            : T extends 'stream'
              ? ReadableStream
              : never
> {
    return axiosInstance({
        method: 'get',
        url: '/assets/' + asset_container_exportable + '/' + asset_id + '/exports/' + format + '',
        params: {
            scale: scale,
            sub_mesh_index: sub_mesh_index,
        },
        headers: headers,
        responseType: responseType || 'arraybuffer',
    });
}

